insert into prompts (title, content, type, author_name, tags, license, status) values
('React Component Generator', 'Generate a modern, accessible React component with TypeScript interfaces, Tailwind CSS styling, responsive design, ARIA attributes, error loading states, and unit test template.\n\nComponent: [name]\nFunctionality: [description]', 'skill', 'community', '{coding,react,typescript,frontend}', 'MIT', 'published'),
('Python API Builder', 'Build a production-ready Python FastAPI endpoint with:\n1. Input validation (Pydantic)\n2. Error handling\n3. Rate limiting\n4. Documentation (OpenAPI)\n5. Unit tests\n\nEndpoint: [description]', 'skill', 'community', '{coding,python,api,backend}', 'MIT', 'published'),
('SQL Query Optimizer', 'Analyze and optimize this SQL query for performance:\n\n```sql\n[Paste query here]\n```\n\nProvide:\n1. Optimized version\n2. Index recommendations\n3. EXPLAIN plan analysis\n4. Alternative approaches', 'prompt', 'community', '{coding,sql,database,optimization}', 'MIT', 'published'),
('Code Review Assistant', 'Review the following code for bugs, performance issues, security vulnerabilities, and style. Provide line-by-line feedback with suggested fixes.\n\n```\n[Paste code here]\n```', 'skill', 'community', '{coding,review,best-practices}', 'MIT', 'published'),
('Docker Compose Setup', 'Create a production-ready Docker Compose configuration for:\n\nServices: [list services]\nRequirements: [specific needs]\n\nInclude:\n1. Health checks\n2. Volume mounts\n3. Environment variables\n4. Network configuration\n5. Restart policies', 'prompt', 'community', '{coding,docker,devops,deployment}', 'MIT', 'published'),
('JavaScript Debugging', 'Debug this JavaScript code and explain the issue:\n\n```javascript\n[Paste code here]\n```\n\nProvide:\n1. Root cause analysis\n2. Fixed code\n3. Prevention tips', 'prompt', 'community', '{coding,javascript,debugging}', 'MIT', 'published'),
('REST API Design', 'Design a RESTful API for [resource] with:\n1. Endpoints (GET, POST, PUT, DELETE)\n2. Request/Response schemas\n3. Authentication\n4. Error codes\n5. Pagination', 'prompt', 'community', '{coding,api,rest,backend}', 'MIT', 'published'),
('Git Workflow Guide', 'Explain the optimal Git workflow for:\n\nTeam size: [number]\nProject type: [type]\n\nInclude:\n1. Branching strategy\n2. Commit conventions\n3. PR review process\n4. Release workflow', 'prompt', 'community', '{coding,git,workflow,collaboration}', 'MIT', 'published'),
('CSS Layout Master', 'Create a CSS layout for:\n\nLayout: [description]\nBrowser support: [requirements]\n\nUse modern CSS (Grid/Flexbox) with fallbacks.', 'prompt', 'community', '{coding,css,frontend,layout}', 'MIT', 'published'),
('TypeScript Types Generator', 'Generate TypeScript types from this API response:\n\n```json\n[Paste JSON here]\n```\n\nInclude:\n1. Interface definitions\n2. Type guards\n3. Generic utilities', 'prompt', 'community', '{coding,typescript,types,api}', 'MIT', 'published'),
('Node.js Microservice', 'Build a Node.js microservice for [functionality] with:\n1. Express/Fastify setup\n2. Middleware (auth, logging, error handling)\n3. Database connection\n4. Health check endpoint\n5. Docker setup', 'skill', 'community', '{coding,nodejs,backend,microservice}', 'MIT', 'published'),
('React Native Screen', 'Create a React Native screen for [feature] with:\n1. Navigation setup\n2. State management\n3. API integration\n4. Loading/error states\n5. Responsive design', 'skill', 'community', '{coding,react-native,mobile}', 'MIT', 'published'),
('CI/CD Pipeline', 'Design a CI/CD pipeline for:\n\nPlatform: [GitHub Actions/GitLab CI]\nStack: [tech stack]\n\nInclude:\n1. Build steps\n2. Test automation\n3. Deployment stages\n4. Rollback strategy', 'prompt', 'community', '{coding,cicd,devops,automation}', 'MIT', 'published'),
('Data Structure Implementation', 'Implement a [data structure] in [language] with:\n1. Core operations\n2. Time complexity analysis\n3. Space complexity analysis\n4. Use cases', 'prompt', 'community', '{coding,algorithms,data-structures}', 'MIT', 'published'),
('Authentication System', 'Build an authentication system with:\n1. JWT tokens\n2. Refresh token rotation\n3. Role-based access\n4. Rate limiting\n5. Session management', 'skill', 'community', '{coding,security,authentication,jwt}', 'MIT', 'published'),
('WebSocket Real-time', 'Implement a WebSocket server for [use case] with:\n1. Connection handling\n2. Room/channel support\n3. Reconnection logic\n4. Message broadcasting', 'skill', 'community', '{coding,websocket,real-time,backend}', 'MIT', 'published'),
('GraphQL API Setup', 'Create a GraphQL API for [resource] with:\n1. Schema definition\n2. Resolvers\n3. Data loaders (N+1 prevention)\n4. Authentication middleware', 'skill', 'community', '{coding,graphql,api,backend}', 'MIT', 'published'),
('Testing Strategy', 'Design a testing strategy for:\n\nApplication: [description]\n\nInclude:\n1. Unit tests\n2. Integration tests\n3. E2E tests\n4. Test data management', 'prompt', 'community', '{coding,testing,qa,best-practices}', 'MIT', 'published'),
('Performance Optimization', 'Optimize this application for performance:\n\n```\n[Paste code/description]\n```\n\nFocus on:\n1. Load time\n2. Runtime efficiency\n3. Memory usage\n4. Bundle size', 'prompt', 'community', '{coding,performance,optimization}', 'MIT', 'published'),
('System Architecture Design', 'Design a system architecture for:\n\nRequirements: [description]\nScale: [expected load]\n\nInclude:\n1. Component diagram\n2. Data flow\n3. Technology choices\n4. Scaling strategy', 'workflow', 'community', '{coding,architecture,system-design}', 'MIT', 'published')
insert into prompts (title, content, type, author_name, tags, license, status) values
('Blog Post Generator', 'Write a comprehensive, SEO-optimized blog post about [topic].\n\nInclude:\n1. Engaging introduction\n2. 5-7 H2/H3 subheadings\n3. Bullet points and lists\n4. FAQ section\n5. Call-to-action conclusion\n\nTarget keyword: [keyword]\nWord count: 1500-2000', 'prompt', 'community', '{writing,seo,blog,content}', 'MIT', 'published'),
('Viral Twitter Thread', 'Write a viral Twitter/X thread about [topic].\n\n- Hook: Bold claim or surprising stat\n- Body: 5-8 tweets with value\n- CTA: Drive engagement\n- Rules: One idea per tweet, line breaks', 'prompt', 'community', '{writing,social-media,marketing}', 'MIT', 'published'),
('Email Sequence Creator', 'Create a 5-email nurture sequence for:\n\nProduct: [description]\nAudience: [target]\n\nInclude:\n1. Subject lines\n2. Preview text\n3. Body copy\n4. CTAs\n5. Send timing', 'prompt', 'community', '{writing,email,marketing,sequence}', 'MIT', 'published'),
('Landing Page Copy', 'Write landing page copy for:\n\nProduct: [description]\nTarget audience: [audience]\n\nInclude:\n1. Headline + subheadline\n2. Hero section\n3. Features/benefits\n4. Social proof\n5. CTA sections', 'prompt', 'community', '{writing,copywriting,landing-page,marketing}', 'MIT', 'published'),
('Product Description', 'Write compelling product descriptions for:\n\nProduct: [name]\nFeatures: [list]\n\nCreate 3 versions:\n1. Short (50 words)\n2. Medium (150 words)\n3. Long (300 words)', 'prompt', 'community', '{writing,copywriting,ecommerce}', 'MIT', 'published'),
('Press Release Writer', 'Write a press release for:\n\nNews: [announcement]\nCompany: [description]\n\nInclude:\n1. Headline\n2. Dateline\n3. Lead paragraph\n4. Body\n5. Boilerplate\n6. Contact info', 'prompt', 'community', '{writing,pr,communications}', 'MIT', 'published'),
('Case Study Creator', 'Write a case study for:\n\nClient: [name]\nChallenge: [problem]\nSolution: [what you did]\nResults: [outcomes]\n\nInclude:\n1. Executive summary\n2. Challenge\n3. Solution\n4. Results\n5. Testimonial', 'prompt', 'community', '{writing,case-study,marketing}', 'MIT', 'published'),
('White Paper Outline', 'Create a detailed white paper outline for:\n\nTopic: [subject]\nAudience: [target]\n\nInclude:\n1. Executive summary\n2. Problem statement\n3. Solution overview\n4. Technical details\n5. Case studies\n6. Conclusion', 'prompt', 'community', '{writing,white-paper,b2b}', 'MIT', 'published'),
('Video Script Writer', 'Write a video script for:\n\nTopic: [subject]\nDuration: [length]\nPlatform: [YouTube/TikTok/etc]\n\nInclude:\n1. Hook (first 5 seconds)\n2. Main content\n3. B-roll suggestions\n4. CTA', 'prompt', 'community', '{writing,video,script,content}', 'MIT', 'published'),
('Podcast Show Notes', 'Create podcast show notes for:\n\nEpisode: [title]\nTopics: [list]\nGuests: [names]\n\nInclude:\n1. Episode summary\n2. Key takeaways\n3. Timestamps\n4. Links mentioned\n5. Guest bios', 'prompt', 'community', '{writing,podcast,show-notes}', 'MIT', 'published'),
('Technical Documentation', 'Write technical documentation for:\n\nFeature/API: [description]\nAudience: [developers/users]\n\nInclude:\n1. Overview\n2. Getting started\n3. API reference\n4. Examples\n5. Troubleshooting', 'skill', 'community', '{writing,documentation,technical}', 'MIT', 'published'),
('User Story Writer', 'Write user stories for:\n\nFeature: [description]\n\nFormat:\n- As a [user type]\n- I want [goal]\n- So that [benefit]\n\nInclude acceptance criteria for each.', 'prompt', 'community', '{writing,agile,product}', 'MIT', 'published'),
('Error Message Copy', 'Write user-friendly error messages for:\n\nScenario: [description]\n\nInclude:\n1. Clear problem statement\n2. Suggested fix\n3. Support contact\n4. Error code reference', 'prompt', 'community', '{writing,ux,error-messages}', 'MIT', 'published'),
('FAQ Page Creator', 'Create an FAQ page for:\n\nProduct/Service: [description]\n\nInclude:\n1. 10-15 common questions\n2. Clear, concise answers\n3. CTA at the end\n4. Search-friendly format', 'prompt', 'community', '{writing,faq,support}', 'MIT', 'published'),
('About Page Writer', 'Write an About page for:\n\nCompany/Person: [description]\n\nInclude:\n1. Origin story\n2. Mission/values\n3. Team intro\n4. Achievements\n5. Future vision', 'prompt', 'community', '{writing,about,brand}', 'MIT', 'published'),
('Newsletter Content', 'Create newsletter content for:\n\nTopic: [subject]\nAudience: [subscribers]\n\nInclude:\n1. Subject line\n2. Preview text\n3. Main story\n4. Quick links\n5. CTA', 'prompt', 'community', '{writing,newsletter,email}', 'MIT', 'published'),
('Ebook Outline', 'Create a detailed ebook outline for:\n\nTopic: [subject]\nTarget audience: [readers]\n\nInclude:\n1. Chapter titles\n2. Key points per chapter\n3. Case studies\n4. Action items', 'prompt', 'community', '{writing,ebook,content}', 'MIT', 'published'),
('Ad Copy Generator', 'Write ad copy for:\n\nPlatform: [Google/Facebook/LinkedIn]\nProduct: [description]\nGoal: [conversions/clicks]\n\nCreate 5 variations with different angles.', 'prompt', 'community', '{writing,advertising,copywriting}', 'MIT', 'published'),
('Product Hunt Launch', 'Create a Product Hunt launch for:\n\nProduct: [name]\nTagline: [one-liner]\n\nInclude:\n1. First comment (maker comment)\n2. Description\n3. Key features\n4. Launch offers', 'prompt', 'community', '{writing,product-hunt,launch}', 'MIT', 'published'),
('Grant Proposal Writer', 'Write a grant proposal for:\n\nProject: [description]\nFunding amount: [amount]\n\nInclude:\n1. Executive summary\n2. Problem statement\n3. Objectives\n4. Methodology\n5. Budget', 'prompt', 'community', '{writing,grant,proposal}', 'MIT', 'published')
insert into prompts (title, content, type, author_name, tags, license, status) values
