('Debate Preparation', 'Prepare for a debate on:\n\nTopic: [subject]\nPosition: [for/against]\n\nInclude:\n1. Main arguments\n2. Supporting evidence\n3. Counterarguments\n4. Rebuttals\n5. Closing statement', 'prompt', 'community', '{education,debate,critical-thinking}', 'MIT', 'published'),
('Field Trip Plan', 'Plan a field trip to:\n\nDestination: [place]\nGrade Level: [level]\n\nInclude:\n1. Learning objectives\n2. Pre-trip activities\n3. During-trip tasks\n4. Post-trip reflection\n5. Assessment', 'prompt', 'community', '{education,field-trip,planning}', 'MIT', 'published'),
('Parent-Teacher Conference', 'Prepare for a parent-teacher conference about:\n\nStudent: [description]\n\nInclude:\n1. Student strengths\n2. Areas for growth\n3. Specific examples\n4. Goals\n5. Support strategies', 'prompt', 'community', '{education,conference,communication}', 'MIT', 'published'),
('Online Course Outline', 'Create an online course outline for:\n\nSubject: [topic]\nLevel: [beginner/advanced]\n\nInclude:\n1. Course objectives\n2. Module structure\n3. Lesson topics\n4. Assessments\n5. Resources', 'prompt', 'community', '{education,online,course}', 'MIT', 'published'),
